from machine import Pin
from ir_rx import NEC_16
import time

def cb(data, addr, ctrl):
    if data == NEC_16.REPEAT:
        print('repeat')
    elif data < 0:
        print('error %d' % data)
    else:
        print('addr %04x cmd %02x' % (addr, data))

ir = NEC_16(Pin({OUT}, Pin.IN), cb)
print('listening')
while True:
    time.sleep_ms(100)
